import sys
import heapq


class HalfDiff:
    def __init__(self):
        self.low = []   # max heap by negative values: smallest floor(n/2) values
        self.high = []  # min heap: remaining values
        self.sum_low = 0
        self.sum_high = 0
        self.n = 0

    def add(self, x):
        self.n += 1

        if self.high and x >= self.high[0]:
            heapq.heappush(self.high, x)
            self.sum_high += x
        else:
            heapq.heappush(self.low, -x)
            self.sum_low += x

        target_low = self.n // 2

        while len(self.low) > target_low:
            y = -heapq.heappop(self.low)
            self.sum_low -= y
            heapq.heappush(self.high, y)
            self.sum_high += y

        while len(self.low) < target_low:
            y = heapq.heappop(self.high)
            self.sum_high -= y
            heapq.heappush(self.low, -y)
            self.sum_low += y

    def value(self):
        return self.sum_high - self.sum_low


def main():
    input = sys.stdin.readline
    N = int(input())
    A = list(map(int, input().split()))

    pref = [0] * (N + 1)
    h = HalfDiff()
    for i, x in enumerate(A):
        h.add(x)
        if (i + 1) % 2 == 0:
            pref[i + 1] = h.value()

    if N % 2 == 0:
        print(pref[N])
        return

    suff = [0] * (N + 1)
    h = HalfDiff()
    for i in range(N - 1, -1, -1):
        h.add(A[i])
        if (N - i) % 2 == 0:
            suff[i] = h.value()

    ans = 0
    for unmatched in range(0, N, 2):
        ans = max(ans, pref[unmatched] + suff[unmatched + 1])

    print(ans)


if __name__ == "__main__":
    main()
